{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "In fasting healthy volunteers, racemic thalidomide, the closest structural analogue sharing the 2,6-dioxopiperidine-3-yl glutarimide moiety, has an absolute oral bioavailability of 80–100% at a 100 mg oral dose, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Absolute oral bioavailability of (S)-thalidomide was approximately 80% in healthy volunteers using an IV-infusion comparator, providing direct evidence that the glutarimide-containing scaffold is well absorbed orally and reinforcing high F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lenalidomide-like 4-amino-2-(2,6-dioxopiperidin-3-yl)isoindolin-1-one. The closest analogue, thalidomide, shows high absolute oral bioavailability (80–100%) in humans, including fasting volunteers and IV-comparator studies. The shared glutarimide and related heterocyclic system, together with the query's increased polarity and solubility from the amino group, support high oral absorption; no affirmative evidence indicates F < 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is present in the evidence set.",
    "Thalidomide differs from the query by the amino substituent and one carbonyl (phthalimide vs isoindolinone), so transferability is strong but not exact.",
    "Thalidomide absorption is slow and may be dose-dependent, adding some uncertainty to extrapolation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

